 return <aside className={warning?'imports-reconciliation-note':'imports-note'} aria-label="Referência da origem"><div><Info size={17}/><strong>{sourceReference(entry)}</strong></div>{entry.source.planilhaArquivo&&<p>{entry.source.planilhaArquivo}</p>}{warning&&<p className="imports-warning-lines">{warning}</p>}</aside>;
